-- Portfolios (docs/plans/portfolios.md): portfolios, memberships, invite links, readable web addresses. Generated by
-- drizzle-kit, then edited before it was ever applied:
-- - Existing rows all go to portfolio 1, "My books" (/my-books/…), whose members are the existing users at their
--   current role; existing admins become the server's administrator.
-- - ALTER TABLE ADD can't add a NOT NULL column without a default, so the added portfolio_id columns keep DEFAULT 1
--   in the database; the Drizzle schema has no default, so the app always has to say which portfolio a row is in.
-- - Property slugs start empty and are filled from the names by fillSlugs (server/db.ts) right after migrating:
--   slugifying a name needs code SQLite doesn't have.
-- Foreign keys are off while migrations run (runMigrations in server/db.ts) and checked afterwards.
CREATE TABLE `invites` (
	`id` integer PRIMARY KEY NOT NULL,
	`portfolio_id` integer NOT NULL,
	`token_hash` text NOT NULL,
	`role` text NOT NULL,
	`note` text DEFAULT '' NOT NULL,
	`created_by` integer,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) NOT NULL,
	`expires_at` text NOT NULL,
	`accepted_at` text,
	`accepted_by` integer,
	`revoked_at` text,
	FOREIGN KEY (`portfolio_id`) REFERENCES `portfolios`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`created_by`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE set null,
	FOREIGN KEY (`accepted_by`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE set null,
	CONSTRAINT "invites_role_check" CHECK("invites"."role" IN ('admin','member','viewer'))
);
--> statement-breakpoint
CREATE UNIQUE INDEX `invites_token_hash_unique` ON `invites` (`token_hash`);--> statement-breakpoint
CREATE INDEX `invites_portfolio` ON `invites` (`portfolio_id`);--> statement-breakpoint
CREATE TABLE `memberships` (
	`user_id` integer NOT NULL,
	`portfolio_id` integer NOT NULL,
	`role` text DEFAULT 'member' NOT NULL,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) NOT NULL,
	PRIMARY KEY(`user_id`, `portfolio_id`),
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`portfolio_id`) REFERENCES `portfolios`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "memberships_role_check" CHECK("memberships"."role" IN ('admin','member','viewer'))
);
